Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : PESK.sink_policy.
Hypothesis LY : PMU.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis PO : PESK.sink_policy_ok P.
Let KL := PECKU.klayout_U L LY.
Let SF := PECKU.sfoot_U L LY.
Abbreviation enc_at := (PEC.enc_at RSEGS EE L PMSP.T3 PMSP.T4).
Hypothesis PB : PESK.push_back_spec RSEGS CAD EE L HI PMSP.T3 PMSP.T4 P.
Hypothesis PUTL : PECSU.put_length_spec L HI P.
Hypothesis VAL : PECVS.validate_fun_spec RSEGS CAD L (pe_validate_enc EE).

