(* [comment removed for export] *)
Section Call.
Hypothesis SPM : PESK.sp_mode P.
Variables (dptr sv : Z) (l : list Z) (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
          (LBX : list (Z * Z)) (cr : credit) (sp r fb cat : Z) (p : list Z).
Variables (xstk : list pstate) (xpos : Z) (xmore xdone xhalt : bool) (xdepth : Z) (xec : bool) (xestk : list eitem) (xedepth xlo xhi : Z) (xbad : bool).
Variables (s : PM.pst) (str : PM.vstr) (sm : PM.strm) (en : PEC.enc) (k : PESK.sink) (e : bool).
Let X : st := ST xstk xpos xmore xdone xhalt xdepth xec xestk xedepth xlo xhi xbad.
(* [comment removed for export] *)
Let XS (a : Z) : st := ST xstk xpos xmore xdone xhalt xdepth xec xestk xedepth (xlo + a) (xhi + a) xbad.
Let n : Z := Z.of_nat (length l).
Hypothesis HH : hi_heap HI (PEC.owned s en k ++ LBX) cr M (m_vmmaps model).
Hypothesis MOK : PMSP.model_ok model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSP.entry CAD L R M sp r 4.
Hypothesis FOK : PMSP.frame_ok CAD L sp fb.
Hypothesis A10 : getr R 10%bv = Z_to_bv 64 (fb + 432).
Hypothesis A11 : getr R 11%bv = Z_to_bv 64 sv.
Hypothesis A13 : getr R 13%bv = Z_to_bv 64 (fb + 8).
Hypothesis SV8 : sv mod 8 = 0.
Hypothesis SVLO : sp <= sv.
Hypothesis SVHI : sv + 16 <= fb.
Hypothesis U0 : L5.u64_at RSEGS M sv dptr.
Hypothesis U8 : L5.u64_at RSEGS M (sv + 8) n.
Hypothesis BYT : L5.bytes_at RSEGS M dptr l.
Hypothesis BOK : bytes_ok l.
Hypothesis N26 : n < 2 ^ 26.
Hypothesis DEF : L5.defined M dptr n.
Hypothesis LOC : (exists B m, In (B, m) (PM.parser_own s) /\ B <= dptr /\ dptr + n <= B + m) \/ (sp <= dptr /\ dptr + n <= fb + 432) \/ (dptr = 0 /\ l = []).
Hypothesis UV : utf8_valid l = true.
Hypothesis CPRE : PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M fb p X s str sm en k e cat.
Hypothesis INCS : incl (PM.vs_own str) LBX.
Hypothesis POK : PECS.payload_ok p.
Hypothesis MP : PECS.mp_enc p X.
Hypothesis HB : PESK.sp_hb P (xhi + (pl_size n + n)).
Hypothesis CRED : PMSP.credit_le (PEC.pot_enc L P en k) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model)
            (en' : PEC.enc) (k' : PESK.sink) (e' : bool) (cr' : credit),
        regs_preserved R R' ->
        PEC.crun_pre RSEGS CAD EE L PMSP.T3 PMSP.T4 P M' fb p (XS (pl_size n + n)) s str sm en' k' e' cat -> (e = true -> e' = true) ->
        L5C.hpres L (PM.parser_own s ++ LBX) sp (PMSP.pm_scr 4) (PEC.W_enc CAD EE fb) M M' ->
        PMSP.credit_keep cr cr' (PEC.pot_enc L P en k) (PEC.pot_enc L P en' k') ->
        model_but_vm model model' -> hi_heap HI (PEC.owned s en' k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.

Let LB : list (Z * Z) := PEC.owned s en k ++ LBX.
