  /\ sp <= fb /\ fb + 832 <= hl_sptop L /\ fb mod 16 = 0
  /\ getr R (PMK.reg 3) = Z_to_bv 64 (pa_gp CAD) /\ getr R (PMK.reg 4) = Z_to_bv 64 (pa_tp CAD)
  /\ hl_img_lo L = 0x10000 /\ hl_img_hi L = 0xee000
  /\ 0 <= n /\ 2 <= pl_size n <= 9
  /\ ((4096 <= dptr /\ dptr + n <= hl_sptop L - 2 ^ 23 /\ (dptr + n <= hl_img_lo L \/ hl_img_hi L <= dptr)
        /\ exists B m, In (B, m) LBc0 /\ B <= dptr /\ dptr + n <= B + m)
       \/ (sp <= dptr /\ dptr + n <= fb + 432) \/ (dptr = 0 /\ n = 0)).
